import { MANAGER_CONTRIBUTION_MARKERS, containsAny } from './textSignals';

export type Pose = 'Explaining' | 'Guarded' | 'Composed' | 'Measured' | 'Considering';

export interface ScriptedReply {
  id: string;
  stage: S02InputStage;
  pose: Pose;
  lines: string[];
}

/** The portrait pose each response style selects. Chosen by rule, never by a model. */
export const POSE_FOR_STYLE: Record<EmployeeResponseStyle, Exclude<Pose, 'Considering'>> = {
  technical_detail: 'Explaining',
  evidence_challenge: 'Guarded',
  composed_disagreement: 'Composed',
  procedural_compliance: 'Measured'
};

