export interface PriorTurnLike {
  stage: S02InputStage;
  employeeLines: string[];
}

export interface ScriptedSelection {
  reply: ScriptedReply;
  style: EmployeeResponseStyle;
}

function linesEqual(a: string[], b: string[]): boolean {
  return a.length === b.length && a.every((line, i) => line === b[i]);
}

function repliesFor(stage: S02InputStage, pose: Pose): ScriptedReply[] {
  return SCRIPTED_REPLIES.filter((reply) => reply.stage === stage && reply.pose === pose);
}

/**
 * How many Considering replies this session has already produced, found by
 * matching the lines of earlier turns. Derived from the turns alone, so it
 * needs no stored counter, is the same on every call with the same turns,
 * and starts again at zero when the session is reset for a replay.
 */
export function consideringCount(priorTurns: PriorTurnLike[]): number {
  const considering = SCRIPTED_REPLIES.filter((reply) => reply.pose === 'Considering');
  return priorTurns.filter((turn) => considering.some((reply) => linesEqual(reply.lines, turn.employeeLines))).length;
}

/**
 * Picks Tomás's scripted reply.
 *
 *  - A Considering reply is used when the manager names their own
 *    contribution, the input tripped no stage prohibition, and it does not
 *    bring in the outage or a named source or assert causality (those
 *    select the Guarded or Composed styles, and he does not open up in
 *    response to them).
 *  - Considering is restrained first, fuller later: the session's first one is
 *    the stage's first (restrained) line; every later one is the stage's last
 *    (fuller) line where it has two. Openness grows only with repeated
 *    acknowledgement, never from the stage alone.
 *  - Otherwise the pose follows the response style, and the stage's variants
 *    alternate with the number of turns already taken in that stage.
 */
export function selectScriptedReply(input: {
  stage: S02InputStage;
  managerInput: string;
  priorTurns: PriorTurnLike[];
  /** True when detectStageViolations found a prohibition in this input. */
  violated: boolean;
}): ScriptedSelection {
  const style = chooseStyle(input.stage, input.managerInput);

  const opensUp = style === 'technical_detail' || style === 'procedural_compliance';

  if (!input.violated && opensUp && containsAny(input.managerInput, MANAGER_CONTRIBUTION_MARKERS)) {
    const options = repliesFor(input.stage, 'Considering');
    if (options.length > 0) {
      const reply = consideringCount(input.priorTurns) === 0 ? options[0] : options[options.length - 1];
      return { reply, style };
    }
  }

  const options = repliesFor(input.stage, POSE_FOR_STYLE[style]);
  const turnsInStage = input.priorTurns.filter((turn) => turn.stage === input.stage).length;
  return { reply: options[turnsInStage % options.length], style };
}
